// WCAG contrast ratio calculator
function hexToRgb(hex) {
  const r = parseInt(hex.slice(1, 3), 16) / 255;
  const g = parseInt(hex.slice(3, 5), 16) / 255;
  const b = parseInt(hex.slice(5, 7), 16) / 255;
  return { r, g, b };
}

function getLuminance(rgb) {
  const { r, g, b } = rgb;
  const [rs, gs, bs] = [r, g, b].map(x => {
    return x <= 0.03928 ? x / 12.92 : Math.pow((x + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * rs + 0.7152 * gs + 0.0722 * bs;
}

function getContrast(hex1, hex2) {
  const lum1 = getLuminance(hexToRgb(hex1));
  const lum2 = getLuminance(hexToRgb(hex2));
  const lighter = Math.max(lum1, lum2);
  const darker = Math.min(lum1, lum2);
  return ((lighter + 0.05) / (darker + 0.05)).toFixed(2);
}

console.log("WARNING TONE (text on background):");
console.log("Text: #c4732c, Background: #fbebd9");
const warningContrast = getContrast("#c4732c", "#fbebd9");
console.log(`Contrast ratio: ${warningContrast}:1`);
console.log(`WCAG AA (4.5:1) requirement: ${warningContrast >= 4.5 ? "PASS" : "FAIL"}`);
console.log("");

console.log("SUCCESS TONE (text on background):");
console.log("Text: #2e7d5b, Background: #e3f0ea");
const successContrast = getContrast("#2e7d5b", "#e3f0ea");
console.log(`Contrast ratio: ${successContrast}:1`);
console.log(`WCAG AA (4.5:1) requirement: ${successContrast >= 4.5 ? "PASS" : "FAIL"}`);
EOF
